mapper.sql:
n.status = 1
AND (
    #{role} = 'admin'
    OR n.type IN ('system', 'notice')
    OR (n.type = 'course' AND EXISTS (
            SELECT 1 FROM selection_record sr
            WHERE sr.course_id = n.course_id AND sr.student_id = #{userId} AND sr.status = 1
        ))
    OR (n.type = 'course' AND EXISTS (
            SELECT 1 FROM course cc
            WHERE cc.id = n.course_id AND cc.teacher_id = #{userId}
        ))
)
